import 'package:activity_files/activity_files.dart';

Future<void> convertGpxToFit(Uint8List bytes) async {
  final imported = await ActivityFiles.import(bytes, useIsolate: true);
  if (imported.hasErrors) {
    throw StateError('Import failed:\n${imported.diagnosticsSummary()}');
  }
  final normalized = ActivityFiles.edit(imported.activity).sortAndDedup().trimInvalid().activity;
  final export = ActivityFiles.export(activity: normalized, to: ActivityFileFormat.fit, runValidation: true);
  final fitBytes = export.asBytes();
}
